function build_flat_hierarchy(
  thread_index: thread_index,
  expanded_folders: string[],
  options = {},
): (
  | {
      type: 'file'
      label: string
      id: id
    }
  | {
      type: 'folder'
      label: string
      id: string
    }
  | {
      type: 'whitespace'
    }
)[] {
  let threads: {
    id: id
    title: string
    folder: string
    creation_time: number
    is_hidden?: bool
  }[] = thread_index
  threads = map(threads ?? {}, ([thread, thread_index_item]) => ({
    ...thread_index_item,
    id: thread,
  }))
  threads = threads.filter(({ is_hidden }) => !is_hidden)

  let root = {}

  for (const thread of threads) {
    let current_children = root

    let dirs = thread.folder.split('/').filter((dir) => dir != '')

    for (const dir of dirs) {
      if (!has(current_children, dir)) {
        current_children[dir] = {
          type: 'folder',
          label: dir,
          creation_time: thread.creation_time,
          children: {},
        }
      }

      current_children = current_children[dir].children
    }

    current_children[thread.id] = {
      type: 'file',
      label: thread.title,
      creation_time: thread.creation_time,
    }
  }

  let whitespace = {
    type: 'whitespace',
  }

  let items = []

  function append_children(children, dir = '') {
    map(children, ([id, child]) => {
      const { type, label, creation_time, children } = child

      if (type == 'file') {
        items.push({
          type,
          label,
          id,
        })
      } else if (type == 'folder') {
        let folder_path = `${dir}${label}`

        items.push({
          type,
          label,
          id: folder_path,
        })

        let is_expanded = has(expanded_folders, folder_path)

        if (is_expanded) {
          append_children(children, `${folder_path}/`)
        }

        items.push(whitespace)
      }
    })
  }

  append_children(root)

  items = map(items, (item, index) => {
    if (item.type == 'whitespace' && items?.[index + 1]?.type == 'whitespace') {
      return
    }
    return item
  })

  return items
}

function render(md: string) {
  return marked.parse(md, {
    gfm: true,
    breaks: true,
  })
}

render = memoize(render)

let ws: WebSocket
let pending_actions: Set<fn> = set()
let pending_requests: Record<id, fn> = {}

function connect() {
  ws = new WebSocket('ws://localhost:8192/api/ws')

  ws.onopen = () => {
    log('Connected!')

    map(pending_actions, call)
  }

  ws.onmessage = receive

  ws.onclose = () => {
    log('Disconnected')

    const delay = ws_retry_delay + random() * ws_max_jitter

    set_timeout(function () {
      log('Reconnecting...')

      connect()
    }, delay)
  }
}

async function perform(
  action: action,
  payload?: object,
  timeout = action_timeout,
  request = random_id(),
): Promise<any> {
  if (!(ws?.readyState == WebSocket.OPEN)) {
    // log(`wait for ws to perform ${action}`)
    pending_actions.add(() => send(action, payload, request))
  } else {
    send(action, payload, request)
  }

  return new Promise((resolve, reject) => {
    pending_requests[request] = resolve

    set_timeout(function () {
      reject(
        err(`response for action ${action} should arrive within ${timeout}ms`),
      )
    }, timeout)
  })
}

async function send(action: action, payload: any, request: id) {
  const request_payload = {
    type: 'request',
    request,
    action,
    payload,
  }

  log('perform', action, payload)

  ws.send(stringify(request_payload))
}

function scroll_by(
  ref,
  distance,
  scroll_behavior: 'smooth' | 'instant' = 'instant',
) {
  if (!ref.current) {
    return
  }

  if (abs(distance) <= 1) {
    distance = ref.current.clientHeight * distance
  }

  ref.current.scrollBy({
    top: distance,
    behavior: scroll_behavior,
  })
}

// let text = identity
function text(s: string) {
  return map(s.split('_'), (word) => {
    return word.slice(0, 1).toUpperCase() + word.slice(1)
  }).join(' ')
}
use({ text })

function trim_start(s: string, char: string = ' '): string {
  if (char === '') return s

  while (s.startsWith(char)) {
    s = s.slice(char.length)
  }
  return s
}

function trim_end(s: string, char: string = ' '): string {
  if (char === '') return s

  while (s.endsWith(char)) {
    s = s.slice(0, -char.length)
  }
  return s
}

function trim(s: string, char: string = ' '): string {
  return trim_end(trim_start(s, char), char)
}

declare global {
  type node = root | id

  type root = number
  type id = string

  type role = 'system' | 'user' | 'assistant' | 'tool'

  type thread_structure = {
    tree: Record<
      node,
      {
        children: node[]
        focus?: node
      }
    >
    roots: root[]
    focus: root
    messages: Record<id, message_structure>
    config?: {
      system_prompt: string
      model: string
      provider: string
    }
  }

  type message_structure = {
    id?: id
    role: role
    content: string
    reasoning?: string
    tools?: tool[]
    usage?: {
      prompt_tokens: number
      completion_tokens: number
      total_tokens: number
    }
    perf?: {
      tokens_per_second: number
      time_to_first_token: number
    }
    has_failed?: bool
    start_time: number
    end_time: number
    model?: string
  }

  type plain_message_structure = {
    role: role
    content: string
  }

  type delta = {
    content: string
    reasoning?: string
  }

  type tool = {
    tool: string
    args: Record<Key, any>
  }


