type textarea = {
  value: string
  placeholder?: string
  set_value: (value: string | ((...args: any) => string)) => void
  [key: Key]: any
}

export function textarea({ value, set_value, ...props }: textarea) {
  const ref = useRef()

  function handle_change(event) {
    set_value(event.target.value)
  }

  useEffect(() => {
    const textarea = ref.current
    if (!textarea) return

    // 1. Temporarily hide scrollbar track to avoid flashing layouts
    const originalOverflow = textarea.style.overflowY
    textarea.style.overflowY = 'hidden'

    // 2. Reset height to 'auto' to allow the textarea to shrink if text was deleted
    textarea.style.height = 'auto'

    // 3. Capture the exact content height calculated by the browser engine
    let targetHeight = textarea.scrollHeight

    // Guard clause: If element is hidden or detached (0px), don't collapse it
    if (targetHeight === 0) {
      textarea.style.overflowY = originalOverflow
      return
    }

    // 4. Handle browser engine edge-cases where borders aren't added to scrollHeight
    const style = window.getComputedStyle(textarea)
    if (style.boxSizing === 'border-box') {
      const borderTop = parseFloat(style.borderTopWidth) || 0
      const borderBottom = parseFloat(style.borderBottomWidth) || 0

      if (textarea.clientHeight === targetHeight) {
        targetHeight += borderTop + borderBottom
      }
    }

    // 5. Apply the calculated height and restore overflow settings
    textarea.style.height = `${targetHeight}px`
    textarea.style.overflowY = originalOverflow
  }, [value])

  useEffect(() => {
    const handleResize = () => {
      const textarea = ref.current
      if (!textarea) return
      textarea.style.height = 'auto'
      textarea.style.height = `${textarea.scrollHeight}px`
    }

    window.addEventListener('resize', handleResize)
    return () => window.removeEventListener('resize', handleResize)
  }, [])

  return h('textarea.textarea', {
    value,
    onchange: handle_change,
    ref,
    ...props,
  })
}
type input = {
  value: string
  placeholder?: string
  set_value: (value: string | ((...args: any) => string)) => void
}

export function input({ value, set_value, ...props }: input) {
  function handle_change(event) {
    set_value(event.target.value)
  }

  return h('input.input', { value, onchange: handle_change, ...props })
}

import { go } from 'fuzzysort'

import { input } from './input'
import { modal } from './modal'
import { scroll } from './scroll'

const max_search_results = 100

const command_prefix = '>'

export function modal_search({ files, commands, shortcuts }) {
  const [open, set_open] = use_state(false)

  const [query, set_query] = use_state('')
  const field = use_ref()
  const focus_element = use_ref()

  // command -> shortut
  let shortcut_map = {}

  map(shortcuts, (shortcut) => {
    const { command, key, when = true } = shortcut

    shortcut_map[command] = key
    use_keyboard(key, commands[command], {
      when,
    })
  })

  use_keyboard('ctrl+p', () => {
    set_query('')
    set_open(true)
  })

  use_keyboard('ctrl+shift+p', () => {
    set_query(command_prefix)
    set_open(true)
  })

  use_keyboard(
    'esc',
    () => {
      set_open(false)
    },
    {
      when: open,
    },
  )

  use_effect(() => {
    if (!open || !field.current) {
      return
    }

    field.current.focus()
  }, [open])

  let items
  if (query.startsWith(command_prefix)) {
    items = map(commands, ([command, fn]) => ({
      // id: command,
      label: text(command),
      info: shortcut_map[command] ?? '',
      fn,
    }))
  } else {
    items = files
  }

  // items = [...items, ...items, ...items]

  let results = search(normalize_query(query), items)

  let first_index = 0
  let last_index = items.length - 1
  const [focus, set_focus] = use_state(0)

  let controls = {
    down() {
      if (focus == last_index) {
        set_focus(first_index)
      } else {
        set_focus((focus) => focus + 1)
      }
    },
    up() {
      if (focus == first_index) {
        set_focus(last_index)
      } else {
        set_focus((focus) => focus - 1)
      }
    },
    select(index) {
      if (results.length > 0) {
        results[index].fn()
        set_open(false)
      }
    },
  }

  use_effect(() => {
    set_focus(0)
  }, [query])

  use_effect(() => {
    focus_element.current?.scrollIntoView?.({
      behavior: 'auto',
      block: 'nearest',
    })
  }, [open, focus])

  use_keyboard('ctrl+j', controls.down, {
    when: open,
  })
  use_keyboard('tab', controls.down, {
    when: open,
  })
  use_keyboard('ctrl+k', controls.up, {
    when: open,
  })
  use_keyboard('shift+tab', controls.up, {
    when: open,
  })
  use_keyboard('enter', () => controls.select(focus), {
    when: open,
  })

  return (
    open &&
    h(
      modal,
      h(
        'modal_search',
        h(
          'modal_search_query',
          h(input, {
            value: query,
            set_value: set_query,
            placeholder: text('search threads by title'),
            ref: field,
            // autofocus: true
          }),
        ),
        h(
          'modal_search_results',
          h(
            scroll,
            map(results, ({ id, label, info, fn }, index) =>
              h(
                'button.modal_search_result',
                {
                  focus: focus == index,
                  onclick: () => controls.select(index),
                  ref: focus == index && focus_element,
                },
                h('modal_search_result_label', label),
                h('modal_search_result_info', info),
              ),
            ),
          ),

