@import 'tailwindcss';

@theme {
  --font-sans: 'Ubuntu Sans', sans-serif;
  --font-serif: 'EB Garamond', serif;
  --font-mono: 'Fira Code', monospace;
  --container-prose: 65ch;
  --container-md: 28rem;
  --spacing-40: 10rem;
  --spacing-96: 24rem;
  --spacing-12: 3rem;
  --spacing-8: 2rem;
  --spacing-6: 1.5rem;
  --spacing-5: 1.25rem;
  --spacing-4: 1rem;
  --spacing-3: 0.75rem;
  --spacing-2: 0.5rem;
  --spacing-1: 0.25rem;

  --color-gray-50: oklch(99.5% 0 0);
  --color-gray-100: oklch(98.5% 0 0);
  --color-gray-150: oklch(97% 0 0);
  --color-gray-200: oklch(95% 0 0);
  --color-gray-250: oklch(92.5% 0 0);
  --color-gray-300: oklch(89% 0 0);
  --color-gray-350: oklch(85% 0 0);
  --color-gray-400: oklch(80% 0 0);
  --color-gray-450: oklch(74% 0 0);
  --color-gray-500: oklch(68% 0 0);
  --color-gray-550: oklch(61% 0 0);
  --color-gray-600: oklch(54% 0 0);
  --color-gray-650: oklch(46% 0 0);
  --color-gray-700: oklch(38% 0 0);
  --color-gray-750: oklch(30% 0 0);
  --color-gray-800: oklch(22% 0 0);
  --color-gray-850: oklch(16% 0 0);
  --color-gray-900: oklch(11% 0 0);

  --color-accent-blue: oklch(61.4% 0.164 255);
  --color-accent-teal: oklch(60.3% 0.098 213);
  --color-accent-green: oklch(59.4% 0.139 147);
  --color-accent-yellow: oklch(67.4% 0.142 76);
  --color-accent-orange: oklch(65.4% 0.196 42);
  --color-accent-red: oklch(60.3% 0.217 22);
  --color-accent-pink: oklch(65.1% 0.158 352);
  --color-accent-purple: oklch(52.5% 0.175 317);
  --color-accent-slate: oklch(60.1% 0.037 247);
}

:root {
  --palette-gray-50: var(--color-gray-50);
  --palette-gray-100: var(--color-gray-100);
  --palette-gray-150: var(--color-gray-150);
  --palette-gray-200: var(--color-gray-200);
  --palette-gray-250: var(--color-gray-250);
  --palette-gray-300: var(--color-gray-300);
  --palette-gray-350: var(--color-gray-350);
  --palette-gray-400: var(--color-gray-400);
  --palette-gray-450: var(--color-gray-450);
  --palette-gray-500: var(--color-gray-500);
  --palette-gray-550: var(--color-gray-550);
  --palette-gray-600: var(--color-gray-600);
  --palette-gray-650: var(--color-gray-650);
  --palette-gray-700: var(--color-gray-700);
  --palette-gray-750: var(--color-gray-750);
  --palette-gray-800: var(--color-gray-800);
  --palette-gray-850: var(--color-gray-850);
  --palette-gray-900: var(--color-gray-900);
  --palette-accent: var(--color-accent-blue);

  --color-surface: var(--color-gray-100);
  --color-surface-semihigh: var(--color-gray-150);
  --color-surface-high: var(--color-gray-200);
  --color-surface-higher: var(--color-gray-250);
  --color-on-surface: var(--color-gray-900);
  --color-on-surface-high: var(--color-gray-900);
  --color-on-surface-low: var(--color-gray-700);
  --color-sidebar: var(--color-gray-250);
  --color-field: var(--color-gray-200);
  --color-scrollbar-thumb: var(--color-gray-400);
  --color-focus: color-mix(in oklab, var(--palette-accent) 20%, transparent);
  --palette\.focus: var(--color-focus);
}

[theme='dark'] {
  --color-surface: var(--color-gray-900);
  --color-surface-semihigh: var(--color-gray-800);
  --color-surface-high: var(--color-gray-750);
  --color-surface-higher: var(--color-gray-700);
  --color-on-surface: var(--color-gray-100);
  --color-on-surface-high: var(--color-gray-50);
  --color-on-surface-low: var(--color-gray-300);
  --color-sidebar: var(--color-gray-700);
  --color-field: var(--color-gray-750);
  --color-scrollbar-thumb: var(--color-gray-600);
  --color-focus: color-mix(in oklab, var(--palette-accent) 50%, transparent);
}

.app {
  @apply flex h-dvh font-sans text-lg;
  background-color: var(--color-surface);
  color: var(--color-on-surface);
}

.sidebar {
  @apply flex h-full w-md flex-col;
  background-color: var(--color-sidebar);
}

.nav_new_thread {
  @apply px-2;
}

.threads {
  @apply grow;
}

.threads_whitespace {
  @apply h-4;
}

.threads_thread,
.threads_folder {
  @apply flex h-8;
}

.threads_folder {
  @apply font-semibold;
  color: var(--color-on-surface-high);
}

.threads_set_thread,
.threads_toggle_folder {
  @apply flex-1 px-2 text-nowrap text-ellipsis;
}

.threads_toggle_folder {
  @apply flex-col justify-end;
}

.threads_delete_thread {
  @apply px-2;
}

.main {
  @apply flex grow flex-col;
}

.status {
  @apply flex h-8 w-full flex-col justify-center px-2;
  background-color: var(--color-surface-semihigh);
  color: var(--color-on-surface-low);
}

.status_folder {
  @apply text-right;
}

